'use strict';
const $=id=>document.getElementById(id),form=$('configForm'),C=ForjaCalc;
let rates={...C.defaults},result=null,params=null,valid=true,photos=[],lastQuote=null;
const money=n=>'Bs '+n.toLocaleString('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2});const num=n=>n.toLocaleString('es-BO',{maximumFractionDigits:1});
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readForm(){const f=new FormData(form);return {roof:f.get('roof'),width:Number(f.get('width')),length:Number(f.get('length')),height:Number(f.get('height')),slope:Number(f.get('slope')),cover:f.get('cover'),finish:f.get('finish'),installation:f.has('installation'),distance:Number(f.get('distance')),client:f.get('client').trim(),location:f.get('location').trim(),notes:f.get('notes').trim()};}
function tableRows(rows){return rows.map(x=>`<tr><td>${escapeHTML(x.name)}<small>${escapeHTML(x.detail)}</small></td><td>${num(x.quantity)} ${x.unit}</td><td>${money(x.amount)}</td></tr>`).join('');}
function costEntries(r){return [['Materiales e insumos',r.materials,'#254d40'],['Fabricación y acabado',r.fabrication,'#5c8270'],['Instalación',r.installation,'#91ae9c'],['Transporte',r.transport,'#c1cfc4'],['Margen del taller',r.margin,'#da502b']];}
function update(){const p=readForm();const error=C.validate(p);valid=!error;$('formError').textContent=error;$('generate').disabled=!valid;$('saveDraft').disabled=!valid;if(!valid){$('total').textContent='Revisa los datos';return;}params=p;result=C.calculate(p,rates);const r=result;
 $('modelTitle').textContent=p.roof==='gable'?'Techo a dos aguas':'Techo a una agua';$('areaBadge').textContent=num(r.area)+' m² de planta';$('geometryInfo').textContent=r.columns+' columnas · altura máx. '+num(p.height+r.rise)+' m';$('total').textContent=money(r.total);$('days').textContent=r.days+' días hábiles';$('timeDetail').textContent=`${Math.ceil(rates.supplyDays)} abastecimiento + ${r.fabricationDays} fabricación${p.installation?' + '+r.installationDays+' instalación':''}`;$('costBars').innerHTML=costEntries(r).filter(x=>x[1]>0).map(x=>`<span title="${x[0]}" style="background:${x[2]};width:${x[1]/r.total*100}%"></span>`).join('');$('costSummary').innerHTML=costEntries(r).map(x=>`<div><span>${x[0]}</span><b>${money(x[1])}</b></div>`).join('');$('billBody').innerHTML=tableRows(r.rows);$('itemCount').textContent=r.rows.length+' partidas';
 $('assumptionsText').innerHTML=`<p>Esta plantilla muestra cantidades geométricas de referencia; no verifica cargas de viento, luces admisibles, resistencia, uniones ni cimentaciones.</p><ul><li>Área en planta: ${num(r.area)} m². Superficie inclinada con aleros: ${num(r.roofArea)} m².</li><li>${r.frames} pórticos y ${r.columns} columnas. Separación longitudinal de referencia: hasta 3 m. Correas: separación de referencia de hasta 1 m sobre la pendiente.</li><li>Acero: ${num(r.steelMeters)} m teóricos. Se agrega ${num(rates.waste)} % y se redondea por tipo de perfil a barras comerciales de 6 m. Es una previsión de compra, no un plano optimizado de corte o empalmes.</li><li>Cubierta: superficie inclinada × ${num(1+rates.waste/100)}. El formato real de las láminas y los traslapes se revisan con el proveedor.</li><li>Fabricación: ${r.fabricationHours} horas-persona a ${money(rates.labor)}/h. Fórmula: 12 h de preparación + 0,16 h/m de acero + 0,24 h/m² de cubierta + acabado (${p.finish==='paint'?'0,06':'0,03'} h/m).</li><li>Instalación: ${r.installationHours} horas-persona${p.installation?' (8 h + 0,20 h/m² + 0,30 h/columna, redondeado hacia arriba)':' · no incluida'}.</li><li>Tiempo con cuadrilla de 2 personas, 8 h/día, fabricación e instalación consecutivas. Abastecimiento simulado: ${Math.ceil(rates.supplyDays)} días. No contempla agenda, clima ni permisos.</li><li>Transporte: ${money(rates.transportBase)} de salida + ${num(p.distance*2)} km ida y vuelta × ${money(rates.transportKm)}.</li><li>Margen: ${num(rates.margin)} % sobre materiales + trabajo + transporte. Impuestos excluidos.</li><li>No incluye canaletas, bajantes, arriostramientos adicionales, anclajes, fundaciones, grúa ni obras civiles. Se definen tras revisar el proyecto.</li></ul>`;
 if(viewer)viewer.draw();
}
// A lightweight orthographic 3D renderer: all members are cuboids in model coordinates.
function makeViewer(canvas,hero=false){const ctx=canvas.getContext('2d');let yaw=-.65,tilt=.48,drag=null;const api={draw,reset(){yaw=-.65;tilt=.48;draw();},rotate(v){yaw+=v;draw();}};
 function draw(){const p=hero?{width:6,length:4,height:2.8,slope:20,roof:'gable',cover:'galvanized'}:params;if(!p)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(w<1||h<1)return;const dpr=Math.min(window.devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle=hero?'#102830':'#e7eeeb';ctx.fillRect(0,0,w,h);
 const W=p.width,L=p.length,H=p.height,rise=W*p.slope/100/(p.roof==='gable'?2:1);const maxH=H+rise;const scale=Math.min((w-75)/(Math.abs(Math.cos(yaw))*(W+1)+Math.abs(Math.sin(yaw))*(L+1)),(h-62)/((W+L)*Math.sin(tilt)*.55+maxH*Math.cos(tilt)));const centerY=h*.56;
 function transform(v){let [x,y,z]=v;x-=W/2;z-=L/2;y-=maxH*.42;const rx=x*Math.cos(yaw)+z*Math.sin(yaw),rz=-x*Math.sin(yaw)+z*Math.cos(yaw);return [rx,y*Math.cos(tilt)-rz*Math.sin(tilt),rz*Math.cos(tilt)+y*Math.sin(tilt)];}
 function project(v){const q=transform(v);return [w/2+q[0]*scale,centerY-q[1]*scale,q[2]];}
 function line(a,b,color,width=1,dash=[]){const pa=project(a),pb=project(b);ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.moveTo(pa[0],pa[1]);ctx.lineTo(pb[0],pb[1]);ctx.stroke();ctx.setLineDash([]);}
 const grid=hero?'#23424a':'#d3dfd7';for(let x=-2;x<=W+2;x++)line([x,0,-2],[x,0,L+2],grid);for(let z=-2;z<=L+2;z++)line([-2,0,z],[W+2,0,z],grid);
 const polys=[];const sides=[[0,1,2,3],[4,7,6,5],[0,4,5,1],[1,5,6,2],[2,6,7,3],[3,7,4,0]];
 function polygon(points,color,stroke){const v=points.map(project);polys.push({v,depth:v.reduce((s,q)=>s+q[2],0)/v.length,color,stroke});}
 function beam(a,b,size=.085){const dir=b.map((v,i)=>v-a[i]);const len=Math.hypot(...dir);if(!len)return;const n=dir.map(v=>v/len);const ref=Math.abs(n[1])>.9?[1,0,0]:[0,1,0];const u=[n[1]*ref[2]-n[2]*ref[1],n[2]*ref[0]-n[0]*ref[2],n[0]*ref[1]-n[1]*ref[0]];const ul=Math.hypot(...u);for(let i=0;i<3;i++)u[i]=u[i]/ul*size/2;const v=[n[1]*u[2]-n[2]*u[1],n[2]*u[0]-n[0]*u[2],n[0]*u[1]-n[1]*u[0]];const vertices=[];for(const end of [a,b])for(const [su,sv]of [[-1,-1],[1,-1],[1,1],[-1,1]])vertices.push(end.map((q,i)=>q+su*u[i]+sv*v[i]));sides.forEach((s,i)=>polygon(s.map(j=>vertices[j]),['#354f55','#6c8787','#4d6a70','#213c45','#90a4a0','#345058'][i]));}
 function roofY(x){return H+(p.roof==='gable'?(1-Math.abs(x-W/2)/(W/2))*rise:x/W*rise);}
 const frames=Math.ceil(L/3)+1;for(let j=0;j<frames;j++){const z=L*j/(frames-1);for(const x of [0,W]){beam([x,0,z],[x,roofY(x),z],.11);polygon([[x-.19,.02,z-.19],[x+.19,.02,z-.19],[x+.19,.02,z+.19],[x-.19,.02,z+.19]],'#79938b');}if(p.roof==='gable'){beam([-.25,roofY(-.25),z],[W/2,H+rise,z],.12);beam([W/2,H+rise,z],[W+.25,roofY(W+.25),z],.12);}else beam([-.25,roofY(-.25),z],[W+.25,roofY(W+.25),z],.12);}
 for(const x of [0,W])beam([x,roofY(x),0],[x,roofY(x),L],.1);
 const segments=Math.ceil((W+.5)/.85);for(let k=0;k<=segments;k++){const x=-.25+(W+.5)*k/segments;beam([x,roofY(x)+.1,-.25],[x,roofY(x)+.1,L+.25],.065);}
 const covering=hero||$('showCover').checked;if(covering){const strips=Math.ceil((L+.5)/.27);for(let i=0;i<strips;i++){const za=-.25+(L+.5)*i/strips,zb=-.25+(L+.5)*(i+1)/strips;const col=hero?(i%2?'#c7d9cc':'#b5cdbd'):(p.cover==='sandwich'?(i%2?'#dde4df':'#cbd8cf'):(i%2?'#aabdb4':'#c0cec5'));const spans=p.roof==='gable'?[[-.25,W/2],[W/2,W+.25]]:[[-.25,W+.25]];for(const [a,b]of spans)polygon([[a,roofY(a)+.16,za],[b,roofY(b)+.16,za],[b,roofY(b)+.16,zb],[a,roofY(a)+.16,zb]],col);}}
 polys.sort((a,b)=>a.depth-b.depth);for(const p of polys){ctx.beginPath();p.v.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();ctx.fillStyle=p.color;ctx.fill();ctx.strokeStyle=p.color;ctx.lineWidth=.4;ctx.stroke();}
 function dimension(a,b,label){const col=hero?'#f3b785':'#9c432b';line(a,b,col,1);for(const point of[a,b]){const q=project(point);ctx.strokeStyle=col;ctx.beginPath();ctx.moveTo(q[0]-3,q[1]-4);ctx.lineTo(q[0]+3,q[1]+4);ctx.stroke();}const q=project(a.map((v,i)=>(v+b[i])/2));ctx.font='600 12px Arial';const tw=ctx.measureText(label).width;ctx.fillStyle=hero?'#102830':'#e7eeeb';ctx.fillRect(q[0]-tw/2-5,q[1]-10,tw+10,20);ctx.fillStyle=col;ctx.textAlign='center';ctx.fillText(label,q[0],q[1]+4);}
 dimension([0,.02,L+.8],[W,.02,L+.8],num(W)+' m');dimension([W+.8,.02,0],[W+.8,.02,L],num(L)+' m');if(!hero)dimension([-.65,0,0],[-.65,H,0],num(H)+' m');
 }
 if(!hero){canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.009;tilt=Math.max(.15,Math.min(.9,tilt+(e.clientY-drag[1])*.006));drag=[e.clientX,e.clientY];draw();});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>drag=null);canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')yaw-=.12;if(e.key==='ArrowRight')yaw+=.12;if(e.key==='ArrowUp')tilt=Math.min(.9,tilt+.08);if(e.key==='ArrowDown')tilt=Math.max(.15,tilt-.08);draw();}});}
 new ResizeObserver(draw).observe(canvas);return api;
}
let viewer=null;viewer=makeViewer($('modelCanvas'));const heroCanvas=$('heroCanvas');const heroViewer=heroCanvas?makeViewer(heroCanvas,true):null;update();if(heroViewer)heroViewer.draw();form.addEventListener('input',update);form.addEventListener('submit',e=>e.preventDefault());$('showCover').addEventListener('change',()=>viewer.draw());$('viewReset').onclick=()=>viewer.reset();$('rotateLeft').onclick=()=>viewer.rotate(-.25);$('rotateRight').onclick=()=>viewer.rotate(.25);
$('reset').onclick=()=>{form.reset();rates={...C.defaults};photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];renderPhotos();$('saveStatus').textContent='Valores de ejemplo restablecidos.';update();viewer.reset();};
function renderPhotos(){const container=$('photoList');container.replaceChildren();photos.forEach((photo,i)=>{const figure=document.createElement('figure'),img=document.createElement('img'),btn=document.createElement('button');img.src=photo.url;img.alt=photo.name;btn.type='button';btn.textContent='×';btn.setAttribute('aria-label','Quitar '+photo.name);btn.onclick=()=>{URL.revokeObjectURL(photo.url);photos.splice(i,1);renderPhotos();};figure.append(img,btn);container.append(figure);});}
$('photos').onchange=e=>{let message='';for(const f of e.target.files){if(photos.length>=3){message='Puedes agregar hasta tres fotos.';break;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){message='Usa imágenes JPG, PNG o WebP de hasta 5 MB.';continue;}photos.push({name:f.name,url:URL.createObjectURL(f)});}renderPhotos();$('formError').textContent=message;e.target.value='';};
$('ratesOpen').onclick=()=>{$('rateFields').innerHTML=C.specs.map(([key,label,unit,min,max])=>`<label>${label}<small>${unit}</small><input name="${key}" type="number" min="${min}" max="${max}" step="${key==='supplyDays'?1:.1}" value="${rates[key]}" required></label>`).join('');$('ratesError').textContent='';$('ratesDialog').showModal();};
$('ratesForm').onsubmit=e=>{e.preventDefault();const next={};const data=new FormData(e.target);for(const [key,,,min,max]of C.specs){next[key]=Number(data.get(key));if(!Number.isFinite(next[key])||next[key]<min||next[key]>max){$('ratesError').textContent='Revisa los valores: '+key;return;}}rates=next;$('ratesDialog').close();update();};
document.querySelectorAll('[data-close]').forEach(btn=>btn.onclick=()=>$(btn.dataset.close).close());
const storageKey='forja-demo-v1';try{$('loadDraft').hidden=!localStorage.getItem(storageKey);}catch{}
$('saveDraft').onclick=()=>{if(!valid)return;try{localStorage.setItem(storageKey,JSON.stringify({params,rates}));$('saveStatus').textContent='Borrador guardado en este navegador. Las fotos no se guardan.';$('loadDraft').hidden=false;}catch{$('saveStatus').textContent='Tu navegador no permite guardar. Puedes descargar los datos al generar el presupuesto.';}};
$('loadDraft').onclick=()=>{try{const d=JSON.parse(localStorage.getItem(storageKey));C.calculate(d.params,d.rates);rates=d.rates;for(const [key,value]of Object.entries(d.params)){const el=form.elements.namedItem(key);if(!el)continue;if(key==='roof')el.value=value;else if(el.type==='checkbox')el.checked=value;else el.value=value;}update();$('saveStatus').textContent='Borrador recuperado.';}catch{$('saveStatus').textContent='No se pudo recuperar un borrador válido.';}};
function quoteHTML(p,r){const title=p.roof==='gable'?'Techo a dos aguas':'Techo a una agua';const date=new Intl.DateTimeFormat('es-BO',{dateStyle:'long',timeZone:'America/La_Paz'}).format(new Date());return `<div class="quote-meta"><p><b>Referencia:</b> ${escapeHTML(p.client||'Proyecto de demostración')}</p><p><b>Localidad:</b> ${escapeHTML(p.location||'Por definir')}</p><p><b>Fecha:</b> ${date} · Simulación sin validez comercial</p><p><b>${title}</b> · ${num(p.width)} × ${num(p.length)} m · altura al alero ${num(p.height)} m · pendiente ${num(p.slope)} %</p><p>Área en planta ${num(r.area)} m² · cubierta inclinada ${num(r.roofArea)} m²</p></div><img class="quote-image" src="${$('modelCanvas').toDataURL('image/png')}" alt="Bosquejo 3D del proyecto"><h3>Materiales e insumos</h3><table><thead><tr><th>Descripción</th><th>Cantidad</th><th>Importe</th></tr></thead><tbody>${tableRows(r.rows)}</tbody></table><div class="quote-summary">${costEntries(r).map(x=>`<p><span>${x[0]}</span><strong>${money(x[1])}</strong></p>`).join('')}</div><div class="quote-total"><span>Total estimado</span><span>${money(r.total)}</span></div><p><b>Plazo estimado: ${r.days} días hábiles.</b> ${Math.ceil(rates.supplyDays)} de abastecimiento + ${r.fabricationDays} de fabricación${p.installation?' + '+r.installationDays+' de instalación':''}. Cuadrilla de dos personas, ocho horas al día.</p><p>Fabricación: ${r.fabricationHours} horas-persona. Instalación: ${r.installationHours} horas-persona. Tarifa: ${money(rates.labor)}/h. Desperdicio previsto: ${num(rates.waste)} %. Margen: ${num(rates.margin)} % sobre costos. Transporte de ida y vuelta: ${num(p.distance*2)} km.</p>${p.notes?'<p><b>Observaciones:</b> '+escapeHTML(p.notes)+'</p>':''}${photos.length?'<div class="quote-photos">'+photos.map(f=>`<img src="${f.url}" alt="${escapeHTML(f.name)}">`).join('')+'</div>':''}<p class="quote-warning"><b>DEMO — no es una oferta ni un cálculo estructural.</b> Precios y perfiles simulados. El taller debe confirmar cargas, luces, arriostramientos, uniones, anclajes, cortes y medidas antes de fabricar. Sin impuestos, obras civiles, cimentaciones, permisos, canaletas, bajantes ni grúa. Plazo sujeto a diseño aprobado, materiales, clima y agenda. La vigencia comercial se define al emitir el presupuesto real.</p>`;}
$('generate').onclick=()=>{update();if(!valid)return;lastQuote={params:{...params},rates:{...rates},result:structuredClone(result),generatedAt:new Date().toISOString(),status:'demo_no_comercial'};const html=quoteHTML(params,result);$('quoteContent').innerHTML=html;$('printArea').innerHTML='<h1>Forma Estructura Metalica · Presupuesto orientativo</h1>'+html;$('quoteDialog').showModal();};$('printQuote').onclick=()=>window.print();$('downloadQuote').onclick=()=>{if(!lastQuote)return;const blob=new Blob([JSON.stringify(lastQuote,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='presupuesto-forma-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
